    const char* const* var_names;
    const char* const* var_regeffects;
    const int* var_positions;
    const int* var_rows;
    const std::uint64_t* regcoef; int n_regcoef;
    const std::uint64_t* arma; int n_arma;
    long neff;
    std::uint64_t loglik, aicc;
